G=load(); import json
d2i,d2o=G['Demo pair 2 input'],G['Demo pair 2 output']

def shapes(g):
    from collections import deque
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append((col,cells))
    return out

def norm(cells):
    my=min(c[0] for c in cells); mx=min(c[1] for c in cells)
    return tuple(sorted((y-my,x-mx) for y,x in cells))

def variants(cells):
    pts=norm(cells); res=set()
    for r in range(4):
        pts=norm([(x,-y) for y,x in pts])
        res.add(pts)
        res.add(norm([(-y,x) for y,x in pts]))  # mirror variants
        res.add(norm([(y,-x) for y,x in pts]))
        res.add(norm([(-y,-x) for y,x in pts]))
    return res

