    for col,cells in si:
        vs=variants(cells)
        match=[c2 for c2,cl in so if norm(cl) in vs or any(norm(cl)==v for v in vs)]
        print(' color',col,'size',len(cells),'norm',norm(cells),'-> matches',match)

def transform(g):
    si=shapes(g)
    bynorm={}
    for col,cells in si: bynorm.setdefault(norm(cells),[]).append(col)
    out=[r[:] for r in g]
